def get_verbosity_flag(verbosity: int, *, adjustment=0) -> str:
    verbosity += adjustment
    if not verbosity:
        return ""

    if verbosity > 0:
        return f"-{'v' * abs(min(verbosity, 3))}"

    return f"-{'q' * abs(max(verbosity, -3))}"


