        config_file.model.dirs.project = [""]
        assert Project.from_config(config_file.model, "foo") is None

    def test_project_dirs_not_directory(self, config_file, temp_dir):
        path = temp_dir / "foo"
        path.touch()
        config_file.model.dirs.project = [str(temp_dir)]
        assert Project.from_config(config_file.model, "foo") is None


